#!/bin/bash

# This script fixes the file ownership issues that may appear when manipulating, on the development machine, files generated by the 'root' user of the Docker container.
#
# Usage: bash fix-permission-issues.bash

################################################################################

# Find files and directories owned by 'root' in the SDE and change ownership to current user and group IDs.
find ${SDE_CONTAINER_ROOT_DIR}/ -user root -print -exec chown ${SDE_USER_ID}:${SDE_GROUP_ID} {} \;
